import json
import sys

def has_default(definition):
    default = definition.get("Default")
    return isinstance(default, dict) and "Value" in default

def validate_values(values, definitions, context):
    errors = []
    if not isinstance(values, dict):
        return [context + " must be a JSON object."]
    definitions = definitions or []
    if not isinstance(definitions, list):
        return [context + " definition is not an array."]
    for definition in definitions:
        if not isinstance(definition, dict):
            errors.append(context + " contains a malformed data-type definition.")
            continue
        name = definition.get("Name")
        if not name:
            errors.append(context + " contains an unnamed data-type definition.")
            continue
        if definition.get("Required") is True and name not in values and not has_default(definition):
            errors.append(context + " is missing required value " + name + ".")
            continue
        if name not in values:
            continue
        value = values[name]
        objectType = definition.get("ObjectType") or definition.get("ClassId")
        if objectType == "workflow.PrimitiveDataType":
            properties = definition.get("Properties") or {}
            kind = properties.get("Type", "string")
            valid = ((kind in ("string", "enum") and isinstance(value, str)) or
                     (kind == "integer" and isinstance(value, int) and not isinstance(value, bool)) or
                     (kind == "float" and isinstance(value, (int, float)) and not isinstance(value, bool)) or
                     (kind == "boolean" and isinstance(value, bool)) or kind == "json")
            if not valid:
                errors.append(context + "." + name + " does not match primitive type " + kind + ".")
                continue
            constraints = properties.get("Constraints") or {}
            minimum, maximum = constraints.get("Min"), constraints.get("Max")
            measured = len(value) if isinstance(value, str) else value
            if minimum not in (None, 0) and measured < minimum:
                errors.append(context + "." + name + " is below its minimum constraint.")
            if maximum not in (None, 0) and measured > maximum:
                errors.append(context + "." + name + " exceeds its maximum constraint.")
            enumList = constraints.get("EnumList") or []
            if kind == "enum" and enumList:
                allowed = [entry.get("Value") for entry in enumList if isinstance(entry, dict)]
                if value not in allowed:
                    errors.append(context + "." + name + " is not in the blueprint enum.")
        elif objectType == "workflow.ArrayDataType":
            if not isinstance(value, list):
                errors.append(context + "." + name + " must be an array.")
            elif definition.get("Min") is not None and len(value) < int(definition["Min"]):
                errors.append(context + "." + name + " has too few items.")
            elif definition.get("Max") is not None and len(value) > int(definition["Max"]):
                errors.append(context + "." + name + " has too many items.")
        elif objectType in ("workflow.CustomDataType", "workflow.DynamicTemplateParserDataType"):
            errors.append(context + "." + name + " uses a custom data type whose complete constraint schema is not present on the blueprint response; live-tenant validation is required and the workflow fails closed.")
        elif objectType and objectType.startswith("workflow.MoReference"):
            if not isinstance(value, dict):
                errors.append(context + "." + name + " must be a managed-object reference object.")
    return errors

def strip_reference(config, blueprint):
    reference = {
        "ClassId": "workload.BlueprintReference",
        "ObjectType": "workload.BlueprintReference",
        "Name": config["Name"],
        "Blueprint": {"ClassId": "mo.MoRef", "ObjectType": "workload.Blueprint", "Moid": blueprint["Moid"]},
        "Input": config.get("Input") or {},
        "InputOverride": config.get("InputOverride") or [],
    }
    constraint = config.get("ResourceConstraint")
    if isinstance(constraint, dict):
        reference["ResourceConstraint"] = {"ClassId": "workload.ResourceConstraint", "ObjectType": "workload.ResourceConstraint", "Input": constraint.get("Input") or {}}
    return reference

